  getTenantQueuesByServiceType(serviceType?: any, config?: any, ...rest: any[]): any {
    let url: any = '/api/tenant/queues?serviceType=' + serviceType;

    return new Promise((resolve, reject) => {
      this.http.get(url, config).subscribe({
        next: (data?: any) => {
          resolve(data);
        },
        error: () => {
          reject();
        }
      });
    });
  }
